package com.studyspace.repo; import java.util.List; import java.util.Optional; import org.springframework.data.mongodb.repository.MongoRepository; import com.studyspace.model.Task; public interface TaskRepository extends MongoRepository<Task,String> { List<Task> findByUserOrderByCompletedAscDueDateAscCreatedAtDesc(String user); Optional<Task> findByIdAndUser(String id,String user); }